begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values
 ('a0000000-0000-0000-0000-000000000001','platform@test.example',now(),'{"display_name":"Platform"}'),
 ('a0000000-0000-0000-0000-000000000002','owner@test.example',now(),'{"display_name":"Owner"}'),
 ('a0000000-0000-0000-0000-000000000003','outsider@test.example',now(),'{"display_name":"Outsider"}');
insert into public.platform_roles(user_id,role) values('a0000000-0000-0000-0000-000000000001','system_admin');
insert into public.disciplines(id,key,name) values('d0000000-0000-0000-0000-000000000001','club-test-unused','Unused'),('d0000000-0000-0000-0000-000000000002','club-test-used','Used'),('d0000000-0000-0000-0000-000000000003','club-test-memory','Memory');
create temporary table created_clubs(label text primary key,value jsonb);
grant select,insert on created_clubs to authenticated;
set local role anon;
select throws_ok($$select public.create_club_workspace('{}',false)$$,'42501',null,'Anonymous users cannot create clubs');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.create_club_workspace('{}',true)$$,'42501','Forbidden','Club owners cannot create managed clubs');
select lives_ok($$insert into created_clubs values('own',public.create_club_workspace('{"organizationName":"Test Club","organizationSlug":"club-admin-test","sectionName":"Sport","sectionSlug":"sport","disciplineId":"d0000000-0000-0000-0000-000000000002","timeZone":"Europe/Stockholm"}',false))$$,'Club and first section are created together without a team');
select is((select count(*)::integer from public.sections where organization_id=(select (value->>'id')::uuid from created_clubs where label='own')),1,'Exactly one first section');
select is((select count(*)::integer from public.teams where organization_id=(select (value->>'id')::uuid from created_clubs where label='own')),0,'Team is optional');
select is((select count(*)::integer from public.activities where organization_id=(select (value->>'id')::uuid from created_clubs where label='own')),0,'No sample activity is created');
select ok(public.has_organization_role((select (value->>'id')::uuid from created_clubs where label='own'),array['owner']),'Self-service creator becomes owner');
select lives_ok($$insert into created_clubs values('team',public.create_club_workspace('{"organizationName":"Team Club","organizationSlug":"club-admin-team-test","sectionName":"Sport","sectionSlug":"sport","disciplineId":"d0000000-0000-0000-0000-000000000002","timeZone":"Europe/Stockholm","teamName":"F2016","teamSlug":"f2016","season":"2026"}',false))$$,'Explicit optional team is created atomically');
select is((select count(*)::integer from public.teams where organization_id=(select (value->>'id')::uuid from created_clubs where label='team')),1,'Optional team exists');
select throws_ok($$select public.create_club_workspace('{"organizationName":"Failed","organizationSlug":"club-admin-rollback-test","sectionName":"Sport","sectionSlug":"sport","disciplineId":"d0000000-0000-0000-0000-000000000099","timeZone":"Europe/Stockholm"}',false)$$,'23503',null,'Missing discipline aborts creation');
select is((select count(*)::integer from public.organizations where slug='club-admin-rollback-test'),0,'Club is rolled back when its section fails');
select throws_ok($$select public.create_club_workspace('{"organizationName":"Failed team","organizationSlug":"club-admin-team-rollback","sectionName":"Sport","sectionSlug":"sport","disciplineId":"d0000000-0000-0000-0000-000000000002","timeZone":"Europe/Stockholm","teamName":"Bad","teamSlug":"../invalid"}',false)$$,'22023','Invalid team','Invalid optional team aborts creation');
select is((select count(*)::integer from public.organizations where slug='club-admin-team-rollback'),0,'Club and section roll back when the team fails');
select throws_ok($$select public.delete_club_section((select (value->>'id')::uuid from created_clubs where label='own'),(select (value->>'sectionId')::uuid from created_clubs where label='own'))$$,'55000','The last section cannot be deleted','Last section is retained');
select lives_ok($$select public.save_club_section((select (value->>'id')::uuid from created_clubs where label='own'),null,'{"name":"Extra","slug":"extra","disciplineId":"d0000000-0000-0000-0000-000000000002"}')$$,'Club owner can add a section');
select lives_ok($$select public.delete_club_section((select (value->>'id')::uuid from created_clubs where label='own'),(select id from public.sections where slug='extra' and organization_id=(select (value->>'id')::uuid from created_clubs where label='own')))$$,'Unused extra section can be removed');
select lives_ok($$select public.save_club_section((select (value->>'id')::uuid from created_clubs where label='team'),null,'{"name":"Extra","slug":"extra","disciplineId":"d0000000-0000-0000-0000-000000000002"}')$$,'Second section permits testing a populated section');
select throws_ok($$select public.delete_club_section((select (value->>'id')::uuid from created_clubs where label='team'),(select (value->>'sectionId')::uuid from created_clubs where label='team'))$$,'55000','Section is in use','Section deletion never cascades to teams');
select throws_ok($$select public.save_club_section((select (value->>'id')::uuid from created_clubs where label='own'),(select (value->>'sectionId')::uuid from created_clubs where label='team'),'{"name":"Forged","slug":"sport","disciplineId":"d0000000-0000-0000-0000-000000000002"}')$$,'P0002','Section not found','Section identity is bound to its club');
select throws_ok($$select public.save_club_section((select (value->>'id')::uuid from created_clubs where label='team'),(select (value->>'sectionId')::uuid from created_clubs where label='team'),'{"name":"Sport","slug":"sport","disciplineId":"d0000000-0000-0000-0000-000000000001"}')$$,'55000','Section discipline is in use','Changing a populated discipline is blocked');
select lives_ok($$select public.save_club_section((select (value->>'id')::uuid from created_clubs where label='team'),(select (value->>'sectionId')::uuid from created_clubs where label='team'),'{"name":"Renamed","slug":"sport","disciplineId":"d0000000-0000-0000-0000-000000000002"}')$$,'Section rename preserves identity and discipline');

select ok((public.club_structure((select (value->>'id')::uuid from created_clubs where label='own'))->'sections'->0->>'canChangeDiscipline')::boolean,'Empty section exposes editable discipline');
select ok(not (select (section->>'canChangeDiscipline')::boolean from jsonb_array_elements(public.club_structure((select (value->>'id')::uuid from created_clubs where label='team'))->'sections') section where section->>'id'=(select value->>'sectionId' from created_clubs where label='team')),'Populated section exposes locked discipline');
insert into public.assistant_memories(organization_id,scope,scope_id,kind,subject,content,created_by) select (value->>'id')::uuid,'section',(value->>'sectionId')::uuid,'instruction','Guide','Keep this',auth.uid() from created_clubs where label='own';
select ok(not (public.club_structure((select (value->>'id')::uuid from created_clubs where label='own'))->'sections'->0->>'canChangeDiscipline')::boolean,'Section memory locks discipline without any teams');
select lives_ok($$select public.save_club_section((select (value->>'id')::uuid from created_clubs where label='own'),(select (value->>'sectionId')::uuid from created_clubs where label='own'),'{"name":"Renamed empty section","slug":"sport","disciplineId":"d0000000-0000-0000-0000-000000000002"}')$$,'Locked section can still be renamed with unchanged discipline');
select throws_ok($$select public.save_club_section((select (value->>'id')::uuid from created_clubs where label='own'),(select (value->>'sectionId')::uuid from created_clubs where label='own'),'{"name":"Renamed empty section","slug":"sport","disciplineId":"d0000000-0000-0000-0000-000000000001"}')$$,'55000','Section discipline is in use','Memory lock also applies when saving');
select ok(not has_function_privilege('authenticated','administration.section_discipline_change_allowed(uuid)','execute'),'Internal lock helper has no client execute privilege');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.club_structure((select (value->>'id')::uuid from created_clubs where label='own'))$$,'42501','Forbidden','Outsider cannot read administrative structure');
select throws_ok($$select public.save_club_metadata((select (value->>'id')::uuid from created_clubs where label='own'),'{"name":"Forged","assistantName":"A","timeZone":"Europe/Stockholm"}')$$,'42501','Forbidden','Outsider cannot update club metadata');
select throws_ok($$select public.system_discipline_usage()$$,'42501','Forbidden','Club membership does not grant platform access');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$insert into created_clubs values('managed',public.create_club_workspace('{"organizationName":"Managed Club","organizationSlug":"club-admin-managed-test","sectionName":"Sport","sectionSlug":"sport","disciplineId":"d0000000-0000-0000-0000-000000000002","timeZone":"Europe/Stockholm"}',true))$$,'Platform admin creates managed club');
select ok(not public.has_organization_role((select (value->>'id')::uuid from created_clubs where label='managed'),array['owner','admin','member']),'Managed creation grants no club membership to the platform admin');
select lives_ok($$select public.save_club_metadata((select (value->>'id')::uuid from created_clubs where label='managed'),'{"name":"Managed Renamed","assistantName":"Assistant","timeZone":"Europe/Stockholm"}')$$,'Platform metadata commands work without membership');
select lives_ok($$delete from public.disciplines where id='d0000000-0000-0000-0000-000000000001'$$,'Unused discipline can be deleted');
select throws_ok($$delete from public.disciplines where id='d0000000-0000-0000-0000-000000000002'$$,'55000','Discipline is in use','Used discipline is protected from direct deletion');
reset role;
insert into public.assistant_memories(organization_id,scope,scope_id,discipline_id,kind,subject,content,created_by) select (value->>'id')::uuid,'organization',(value->>'id')::uuid,'d0000000-0000-0000-0000-000000000003','instruction','Guide','Keep this','a0000000-0000-0000-0000-000000000002' from created_clubs where label='own';
set local role authenticated;
select throws_ok($$delete from public.disciplines where id='d0000000-0000-0000-0000-000000000003'$$,'55000','Discipline is in use','Discipline memory is not detached by ON DELETE SET NULL');
select ok((select in_use from public.system_discipline_usage() where id='d0000000-0000-0000-0000-000000000003'),'Usage includes saved memory outside platform member visibility');
select ok(not has_function_privilege('anon','public.create_club_workspace(jsonb,boolean)','execute'),'Anonymous create RPC privilege is revoked');
select ok(not has_function_privilege('authenticated','administration.discipline_used(uuid)','execute'),'Internal usage helper cannot be called directly');
select ok(not (select prosecdef from pg_proc where oid='public.create_club_workspace(jsonb,boolean)'::regprocedure),'Exposed create wrapper is security invoker');

select ok(not public.club_slug_available('club-admin-managed-test'),'Occupied slug is unavailable');
select ok(public.club_slug_available('club-admin-managed-test',(select (value->>'id')::uuid from created_clubs where label='managed')),'Own unchanged slug is available');
select lives_ok($$select public.save_club_metadata((select (value->>'id')::uuid from created_clubs where label='managed'),'{"name":"Managed","slug":"club-admin-renamed","assistantName":"A","timeZone":"Europe/Stockholm"}')$$,'Administrator can change slug');
select is((public.club_structure((select (value->>'id')::uuid from created_clubs where label='managed')))->'organization'->>'slug','club-admin-renamed','Persisted structure contains the new URL');
select throws_ok($$select public.save_club_metadata((select (value->>'id')::uuid from created_clubs where label='managed'),'{"name":"Managed","slug":"club-admin-test","assistantName":"A","timeZone":"Europe/Stockholm"}')$$,'23505',null,'Occupied slug cannot be saved');
select throws_ok($$select public.save_club_metadata((select (value->>'id')::uuid from created_clubs where label='managed'),'{"name":"Managed","slug":"../bad","assistantName":"A","timeZone":"Europe/Stockholm"}')$$,'22023','Invalid club','Invalid path is rejected');
select lives_ok($$insert into public.discipline_categories(key,name) values('test-category','Test')$$,'System admin can create category');
select lives_ok($$update public.discipline_categories set name='Changed' where key='test-category'$$,'Category display name can change');
select lives_ok($$update public.disciplines set category='test-category' where id='d0000000-0000-0000-0000-000000000002'$$,'Existing discipline can select category');
select throws_ok($$delete from public.discipline_categories where key='test-category'$$,'23503',null,'Used category is protected by foreign key');
select throws_ok($$update public.disciplines set category='missing-category' where id='d0000000-0000-0000-0000-000000000002'$$,'23503',null,'Unknown category cannot be saved');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select ok(not public.club_slug_available('club-admin-test'),'Availability checks clubs outside membership');
select throws_ok($$select public.club_slug_available('club-admin-test',(select (value->>'id')::uuid from created_clubs where label='own'))$$,'42501','Forbidden','Outsider cannot exclude a club from availability');
select throws_ok($$insert into public.discipline_categories(key,name) values('forged','Forged')$$,'42501',null,'Ordinary members cannot create categories');
with changes as (update public.discipline_categories set name='Forged' where key='test-category' returning key) select is((select count(*)::integer from changes),0,'Ordinary members cannot rename categories');
with changes as (delete from public.discipline_categories where key='test-category' returning key) select is((select count(*)::integer from changes),0,'Ordinary members cannot delete categories');
select ok(not has_function_privilege('anon','public.club_slug_available(text,uuid)','execute'),'Anonymous availability privilege is revoked');
select ok(not has_column_privilege('authenticated','public.discipline_categories','key','update'),'Category keys cannot be renamed');
select * from finish();
rollback;
